CREATE TYPE public.app_role AS ENUM ('admin');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own role" ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated;
CREATE TABLE public.clinic_media (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slot text NOT NULL CHECK(slot IN ('hero','intro','doctor','gallery')), path text NOT NULL, url text NOT NULL, caption text NOT NULL DEFAULT '', media_type text NOT NULL CHECK(media_type IN ('image','video')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.clinic_media TO anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.clinic_media TO authenticated;
GRANT ALL ON public.clinic_media TO service_role;
ALTER TABLE public.clinic_media ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public clinic media" ON public.clinic_media FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY "Admin media writes" ON public.clinic_media FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.testimonials (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, quote text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.testimonials TO anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.testimonials TO authenticated;
GRANT ALL ON public.testimonials TO service_role;
ALTER TABLE public.testimonials ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public testimonials" ON public.testimonials FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY "Admin testimonial writes" ON public.testimonials FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.appointments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(name) BETWEEN 2 AND 100), phone text NOT NULL CHECK(phone ~ '^[0-9+ ()-]{8,20}$'), service text NOT NULL CHECK(length(service) BETWEEN 2 AND 100), preferred_date date NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT INSERT ON public.appointments TO anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.appointments TO authenticated;
GRANT ALL ON public.appointments TO service_role;
ALTER TABLE public.appointments ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public appointment requests" ON public.appointments FOR INSERT TO anon,authenticated WITH CHECK(true);
CREATE POLICY "Only admin reads appointments" ON public.appointments FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE POLICY "Only admin changes appointments" ON public.appointments FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE POLICY "Only admin deletes appointments" ON public.appointments FOR DELETE TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE POLICY "Admin uploads clinic files" ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='clinic-media' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY "Admin reads clinic files" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='clinic-media' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY "Admin changes clinic files" ON storage.objects FOR UPDATE TO authenticated USING(bucket_id='clinic-media' AND public.has_role(auth.uid(),'admin')) WITH CHECK(bucket_id='clinic-media' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY "Admin deletes clinic files" ON storage.objects FOR DELETE TO authenticated USING(bucket_id='clinic-media' AND public.has_role(auth.uid(),'admin'));